WITH filtered AS (SELECT *, DATE_TRUNC('week', txn_time) AS txn_time_period, COALESCE(merchant, 'UNKNOWN') AS merchant_clean FROM transactions WHERE txn_time >= TIMESTAMP '2024-01-09 09:00:00' AND HOUR(txn_time) BETWEEN 12 AND 15), flagged AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM filtered), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT burst_id, MIN(txn_time_period) AS first_seen, MIN(txn_time) AS first_seen_2, SUM(CASE WHEN merchant = 'Shell' THEN burst_id ELSE 0 END) AS shell_burst_id, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list FROM islands GROUP BY burst_id ORDER BY shell_burst_id NULLS LAST
